function stripOuter(s: string): string {
  const stack: number[] = [];
  const parts: string[] = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") stack.push(i);
    else {
      const start = stack.pop()!;
      if (stack.length === 0) parts.push(s.slice(start + 1, i)); // a whole group just closed
    }
  }
  return parts.join("");
}

